    // Normalize coordinates to 0-1 range
    // outputs.push(shape.x / CANVAS_SIZE_W);
    console.log(shape.x/64 )
    console.log(shape.x / CANVAS_SIZE_W)
    console.log(shape.x / GRID_SIZE_W)

