// At the top with other global variables
let globalProgress = 0;
let globalPhase = 0;
let pauseTimer = 0;
let pauseDuration = 180; // Number of frames to pause (60 frames = 1 second)


// Alpha values for each layer (0-255)
let alphas = {
  starPattern: 10,
  hyperPattern: 30,
  spiralPattern: 140,
  crossPattern: 100
};

// Geometric parameters
let params = {
  starPoints: 8,
