async function loadTransformers() {
  try {
    const module = await import(
      "https://cdn.jsdelivr.net/npm/@huggingface/transformers@3.4.0"
    );
    const { pipeline } = module;
    return pipeline;
  } catch (error) {
    console.error("Failed to load transformers.js", error);
  }
}

