    // Draw the webcam frame
    ctx.drawImage(webcam.elt, 0, 0, webcam.width, webcam.height);

    // Convert to base64
    const base64Data = tempCanvas.toDataURL('image/jpeg');
    capturedImage = loadImage(base64Data); // Store for display
    resolve(base64Data);
  });
