function draw() {
  background(0);

  // Lighting
  ambientLight(60);
  directionalLight(200, 200, 200, 0.5, 1, -0.5);

  // Camera setup
  rotateX(PI/2.8);
  translate(-w/2, -h/2);

  // Update and draw terrain
  flying -= 0.028;
  let yoff = flying;

  for (let y = 0; y < rows; y++) {
    let xoff = 0;
