  if (key === ' ' && modelLoadedB) {
    inferenceActive = true;
    continuousInference = false;
    isCapturingMode = true;
  }

  // Toggle continuous inference with 'c'
  if (key === 'c' && modelLoadedB) {
    continuousInference = !continuousInference;
    if (continuousInference) {
      inferenceActive = true;
      isCapturingMode = true;
    }
  }
}

