// Add keyboard shortcuts
function keyPressed() {
  if (key === 'd' || key === 'D') {
    showDebug = !showDebug;
  } else if (key === 'r' || key === 'R') {
    // Reset effect
    isFrozen = false;
    timeSinceFreeze = 0;
    timeSinceKeyframe = 0;
  } else if (key === 'f' || key === 'F') {
    // Force a freeze
    forceTrigger = true;
  } else if (key === '1') {
    // Preset: Subtle effect
    frameHoldDuration = 60;
    motionThreshold = 40;
    displacementStrength = 3.0;
    blockSize = 8;
    glitchProbability = 0.01;
  } else if (key === '2') {
    // Preset: Medium effect
    frameHoldDuration = 120;
    motionThreshold = 30;
    displacementStrength = 8.0;
    blockSize = 16;
    glitchProbability = 0.03;
  } else if (key === '3') {
    // Preset: Extreme effect
    frameHoldDuration = 200;
    motionThreshold = 20;
    displacementStrength = 15.0;
    blockSize = 32;
    glitchProbability = 0.05;
  }
}

