  [233, 30, 99],           // Pink
];
let currentPalette = 0;    // Start with black
let curveFactor = 0.3;     // How curvy the lines are (0 = straight, 1 = very curvy)

// Circuit components definitions
const COMPONENTS = {
  RESISTOR: 0,
  CAPACITOR: 1,
  // INDUCTOR removed
  DIODE: 3,
