// function to use 1D array and fake the extra two dimensions --> 3D
function IX(x, y) {
  return x + y * N;
}

// Fluid cube class
class Fluid {
  constructor(dt, diffusion, viscosity) {
    this.size = N;
    this.dt = dt;
    this.diff = diffusion;
    this.visc = viscosity;

    this.s = new Array(N * N).fill(0);
    this.density = new Array(N * N).fill(0);

    this.Vx = new Array(N * N).fill(0);
    this.Vy = new Array(N * N).fill(0);

    this.Vx0 = new Array(N * N).fill(0);
    this.Vy0 = new Array(N * N).fill(0);
  }

  // step method
  step() {
    let N = this.size;
    let visc = this.visc;
    let diff = this.diff;
    let dt = this.dt;
    let Vx = this.Vx;
    let Vy = this.Vy;
    let Vx0 = this.Vx0;
    let Vy0 = this.Vy0;
    let s = this.s;
    let density = this.density;

    diffuse(1, Vx0, Vx, visc, dt);
    diffuse(2, Vy0, Vy, visc, dt);

    project(Vx0, Vy0, Vx, Vy);

    advect(1, Vx, Vx0, Vx0, Vy0, dt);
    advect(2, Vy, Vy0, Vx0, Vy0, dt);

    project(Vx, Vy, Vx0, Vy0);
    diffuse(0, s, density, diff, dt);
    advect(0, density, s, Vx, Vy, dt);
  }

  // method to add density
  addDensity(x, y, amount) {
    let index = IX(x, y);
    this.density[index] += amount;
  }

  // method to add velocity
  addVelocity(x, y, amountX, amountY) {
    let index = IX(x, y);
    this.Vx[index] += amountX;
    this.Vy[index] += amountY;
  }

  // function to render density
  renderD() {
    colorMode(HSB, 255);
    for (let i = 0; i < N; i++) {
      for (let j = 0; j < N; j++) {
        let x = i * SCALE;
        let y = j * SCALE;
        let d = this.density[IX(i, j)];
        fill((d + 50) % 255,200,d);
        noStroke();
        square(x, y, SCALE);
      }
    }
  }

  // function to render velocity
  renderV() {
    for (let i = 0; i < N; i++) {
      for (let j = 0; j < N; j++) {
        let x = i * SCALE;
        let y = j * SCALE;
        let vx = this.Vx[IX(i, j)];
        let vy = this.Vy[IX(i, j)];
       // stroke(0);
        stroke(255);

        if (!(abs(vx) < 0.1 && abs(vy) <= 0.1)) {
          line(x, y, x + vx * SCALE, y + vy * SCALE);
        }
      }
    }
  }
  fadeD() {
    for (let i = 0; i < this.density.length; i++) {
      //let d = density[i];
      this.density = constrain(this.density-0.02, 0, 255);
    }
  }

}

let img;
let fluid;
let rugPixels = [];
let margin = 100;
let pixelSize = 4;
let meltStartTime;
let meltDuration = 5; // seconds
let isMelting = false;
let meltProgress = 0;
let lastMeltY = 0;

function preload() {
  img = loadImage('rug3.png');
}

function setup() {
  createCanvas(1080, 1080);
  pixelDensity(1);
  noSmooth();

  // Initialize fluid
   fluid = new Fluid(0.1, 0.0001, 0.8);  // Much higher viscosity


  resetMelt();
}

function resetMelt() {
  rugPixels = [];
  isMelting = true;
  meltStartTime = millis();

  // Resize image to fit within canvas margins
  let aspectRatio = img.width / img.height;
  let maxHeight = height - 2 * margin;
  let maxWidth = width - 2 * margin;
  let newHeight = maxHeight;
  let newWidth = maxHeight * aspectRatio;

  if (newWidth > maxWidth) {
    newWidth = maxWidth;
    newHeight = maxWidth / aspectRatio;
  }

  // Calculate position to center the image
  let x = (width - newWidth) / 2;
  let y = margin;

  img.resize(newWidth, newHeight);
  img.loadPixels();

  // Store pixel information with fluid simulation coordinates
  for (let i = 0; i < img.width; i += pixelSize) {
    for (let j = 0; j < img.height; j += pixelSize) {
      let index = 4 * (j * img.width + i);
      if (img.pixels[index + 3] > 0) {
        let fluidX = floor(map(i, 0, img.width, 0, N));
        let fluidY = floor(map(j, 0, img.height, 0, N));
        rugPixels.push({
          x: x + i,
          y: y + j,
          origX: x + i,
          origY: y + j,
          fluidX: fluidX,
          fluidY: fluidY,
          r: img.pixels[index],
          g: img.pixels[index + 1],
          b: img.pixels[index + 2],
          a: img.pixels[index + 3],
        });
      }
    }
  }
}

function draw() {
  background(255);

  // Slowly increase melt progress
  meltProgress += 0.001;

  // Calculate current melt line
  let meltLine = height - margin -meltProgress * (height - 2 * margin);

  // Add density only at the current melt line
  for (let i = 1; i < N-1; i++) {
    if (random() < 0.1) {  // Randomly initiate melting points
      let y = floor(map(meltLine, 0, height, 0, N));
      fluid.addDensity(i, y, 50);
      fluid.addVelocity(i, y, random(-0.2, 0.2), 0.5);
    }
  }

  fluid.step();

  // Draw pixels with melting effect
  noStroke();
  rugPixels.forEach(p => {
    let y = p.origY;
    let x = p.origX;

    if (y > meltLine - 20) {  // Start affecting pixels near melt line
      let fluidX = floor(map(x, 0, width, 0, N));
      let fluidY = floor(map(y, 0, height, 0, N));
      let idx = IX(fluidX, fluidY);

      // Get fluid velocities with smoothing
      let vx = fluid.Vx[idx] * 0.5;
      let vy = fluid.Vy[idx] * 0.5;

      // Apply fluid movement with cohesion
      p.x += vx;
      p.y += vy;

      // Add cohesion by limiting distance from original position
      let dx = p.x - p.origX;
      let dy = p.y - p.origY;
      let dist = sqrt(dx * dx + dy * dy);
      if (dist > 30) {
        let angle = atan2(dy, dx);
        p.x = p.origX + cos(angle) * 30;
        p.y = p.origY + sin(angle) * 30;
      }
    }

    fill(p.r, p.g, p.b, p.a);
    rect(p.x, p.y, pixelSize, pixelSize);
  });
}

