  ));
}

function draw() {
  background(255);

  // Draw boundary
  noFill();
  strokeWeight(1);
  stroke(200);
  rect(BOUNDARY_MARGIN, BOUNDARY_MARGIN, 
       width - 2 * BOUNDARY_MARGIN, 
       height - 2 * BOUNDARY_MARGIN);

  for (const snake of snakes) {
    snake.move();

    for (const otherSnake of snakes) {
