    rotateZ(time + i);
    rotateX(time * TAU/4);
    rotateY(i);

    // Calculate varying hue
    let hue = (baseHue + sin(time + i) * TAU/36) % TAU;

    // Set color with full saturation and brightness
    fill(hue * (360/TAU), 80, 100);

