      let y1 = sin(angle) * radius;
      let x2 = cos(angle + TAU/12) * radius;
      let y2 = sin(angle + TAU/12) * radius;

      vertex(0, 0, -TAU);
      vertex(x1, y1, 0);
      vertex(x2, y2, 0);
      endShape();
    }
    pop();

