    this.acc = createVector(0, 0);
    this.size = size || random(20, 40);
    this.angle = random(TWO_PI);
    this.angularVel = 0;
    this.angularAcc = 0;
    this.mass = this.size * this.size;
    this.color = color(random(360), random(20, 40), random(60, 80), 0.7);
    this.settled = false;
  }

  calculateVertices() {
    return [
      createVector(
        this.pos.x + cos(this.angle) * this.size,
        this.pos.y + sin(this.angle) * this.size
      ),
      createVector(
        this.pos.x + cos(this.angle + TWO_PI/3) * this.size,
        this.pos.y + sin(this.angle + TWO_PI/3) * this.size
      ),
      createVector(
        this.pos.x + cos(this.angle + 2*TWO_PI/3) * this.size,
        this.pos.y + sin(this.angle + 2*TWO_PI/3) * this.size
      )
    ];
  }

  applyForce(force) {
    let f = p5.Vector.div(force, this.mass);
    this.acc.add(f);
  }

  attract(other) {
    let force = p5.Vector.sub(this.pos, other.pos);
    let distance = force.mag();
    distance = constrain(distance, 5, 25);
    // Reduced gravitational constant
    let G = 0.1;
    let strength = (G * this.mass * other.mass) / (distance * distance);
    force.setMag(strength);
    return force;
  }

  checkCollision(other) {
    // First do a quick distance check
    let minDist = this.size + other.size;
    if (p5.Vector.dist(this.pos, other.pos) > minDist * 1.5) {
      return false;
    }

    let vertices1 = this.calculateVertices();
    let vertices2 = other.calculateVertices();

    // Check for intersection between any two line segments
    for (let i = 0; i < 3; i++) {
      for (let j = 0; j < 3; j++) {
        let a1 = vertices1[i];
        let a2 = vertices1[(i + 1) % 3];
        let b1 = vertices2[j];
        let b2 = vertices2[(j + 1) % 3];

        if (this.lineIntersection(a1, a2, b1, b2)) {
          return true;
        }
      }
    }
    return false;
  }

  lineIntersection(a1, a2, b1, b2) {
    let denominator = (b2.y - b1.y) * (a2.x - a1.x) - (b2.x - b1.x) * (a2.y - a1.y);
    if (denominator === 0) return false;

    let ua = ((b2.x - b1.x) * (a1.y - b1.y) - (b2.y - b1.y) * (a1.x - b1.x)) / denominator;
    let ub = ((a2.x - a1.x) * (a1.y - b1.y) - (a2.y - a1.y) * (a1.x - b1.x)) / denominator;

    return ua > 0 && ua < 1 && ub > 0 && ub < 1;
  }

  handleCollision(other) {
    // Strong separation force
    let away = p5.Vector.sub(this.pos, other.pos);
    let overlap = (this.size + other.size) - away.mag();
    if (overlap > 0) {
      away.normalize();
      away.mult(overlap * 1.1); // Push slightly more than the overlap
      if (!this.settled) this.pos.add(away.mult(0.5));
      if (!other.settled) other.pos.sub(away.mult(0.5));
    }

    // Stop movement on collision
    if (!this.settled) {
      this.vel.mult(0.5);
      this.angularVel *= 0.5;
    }
    if (!other.settled) {
      other.vel.mult(0.5);
      other.angularVel *= 0.5;
    }

    // Check if triangles should settle
    let speed = this.vel.mag() + other.vel.mag();
    if (speed < 0.1) {
      this.settled = true;
      other.settled = true;
    }
  }

  update() {
    if (this.settled) return;

    this.vel.add(this.acc);
    this.vel.mult(0.98); // Increased drag for slower movement
    this.pos.add(this.vel);

    this.angularVel += this.angularAcc;
    this.angularVel *= 0.98;
    this.angle += this.angularVel;

    this.acc.mult(0);
    this.angularAcc = 0;

    // Settle if moving very slowly
    if (this.vel.mag() < 0.01) {
      this.settled = true;
    }
  }

  show() {
    push();
    colorMode(HSB, 360, 100, 100, 1);
    stroke(0);
    strokeWeight(1);
    fill(this.color);

    beginShape();
    let vertices = this.calculateVertices();
    for (let v of vertices) {
      vertex(v.x, v.y);
    }
    endShape(CLOSE);
    pop();
  }
}

