      let t1 = triangles[i];

      if (!t1.settled) {
        // Reduced gravitational force
        let force = centerTriangle.attract(t1);
        force.mult(0.5); // Further reduce force
        t1.applyForce(force);

        // Check collisions
        for (let j = 0; j < triangles.length; j++) {
          if (i !== j) {
            let t2 = triangles[j];
            if (t1.checkCollision(t2)) {
              t1.handleCollision(t2);
            }
          }
        }

        t1.update();
      }
    }
  }

  // Draw all triangles
  for (let triangle of triangles) {
    triangle.show();
  }
}

