    // Only save unique frames
    if (processedFrames.length === 0 || 
        !arraysEqual(frameData, processedFrames[processedFrames.length - 1])) {
      processedFrames.push(frameData);
    }

    // Debug visualization
    drawDebugView(frameData);
  }
}

